# AWX settings override – generated by bootstrap_awx.py
# DB, Redis, and secret credentials arrive via docker-compose environment variables.
import os

ALLOWED_HOSTS = ['*']

# Public-facing origins AWX must trust (scheme matters in Django 4.x).
CSRF_TRUSTED_ORIGINS = ['http://127.0.0.1', 'http://127.0.0.1:18052']

# nginx terminates TLS and forwards the original scheme in X-Forwarded-Proto;
# this lets Django compute request.is_secure() correctly behind the proxy.
SECURE_PROXY_SSL_HEADER = ('HTTP_X_FORWARDED_PROTO', 'https')

# Without TLS the Secure cookie flag would prevent the browser from ever
# sending the session/CSRF cookies back, breaking login.
SESSION_COOKIE_SECURE = False
CSRF_COOKIE_SECURE = False

SECRET_KEY = os.environ.get('SECRET_KEY', '')

DATABASES = {
    'default': {
        'ATOMIC_REQUESTS': True,
        'ENGINE': 'awx.main.db.profiled_pg',
        'NAME': os.environ.get('DATABASE_NAME', 'awx'),
        'USER': os.environ.get('DATABASE_USER', 'awx'),
        'PASSWORD': os.environ.get('DATABASE_PASSWORD', ''),
        'HOST': os.environ.get('DATABASE_HOST', 'localhost'),
        'PORT': int(os.environ.get('DATABASE_PORT', '5432')),
    }
}

CHANNEL_LAYERS = {
    "default": {
        "BACKEND": "channels_redis.core.RedisChannelLayer",
        "CONFIG": {
            "hosts": [(
                os.environ.get('REDIS_HOST', 'localhost'),
                int(os.environ.get('REDIS_PORT', '6379')),
            )],
        },
    }
}

CACHES = {
    "default": {
        "BACKEND": "django.core.cache.backends.locmem.LocMemCache",
    }
}

BROKER_URL = "redis://{}:{}/0".format(
    os.environ.get('REDIS_HOST', 'localhost'),
    os.environ.get('REDIS_PORT', '6379'),
)

AWX_ISOLATION_SHOW_PATHS = []

AWX_ISOLATION_BASE_PATH = '/awxdata'

# Broadcast websocket relay (awx.main.wsrelay): the awx_task node connects to the
# awx_web node to forward live job events. AWX defaults to https://<web>:443, but
# the web container serves plain HTTP on port 80 over the internal docker network
# (its nginx proxies /websocket to daphne). Point the relay there so live job
# output streams instead of failing with "Connect call failed ...:443".
# BROADCAST_WEBSOCKET_SECRET is supplied via the .awx.env file (shared by both
# the web and task containers).
BROADCAST_WEBSOCKET_PROTOCOL = 'http'
BROADCAST_WEBSOCKET_PORT = 80
BROADCAST_WEBSOCKET_VERIFY_CERT = False
